REVOKE ALL ON FUNCTION erp.validate_manual_deur_physical_occurrence(erp.deurs,timestamptz,timestamptz),erp.manual_deur_has_only_encoding_bootstrap(erp.deurs) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION erp.command_record_manual_deur_activity(jsonb),erp.command_record_manual_deur_travel_checkpoint(jsonb),erp.command_record_manual_deur_refuel(jsonb),erp.command_complete_manual_deur_shift(jsonb) FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION erp.command_record_manual_deur_activity(jsonb),erp.command_record_manual_deur_travel_checkpoint(jsonb),erp.command_record_manual_deur_refuel(jsonb),erp.command_complete_manual_deur_shift(jsonb) TO authenticated;
COMMENT ON FUNCTION erp.validate_manual_deur_physical_occurrence(erp.deurs,timestamptz,timestamptz) IS 'MANUAL_WEB-only physical-occurrence validation: work date is authoritative, while server encoding timestamps remain immutable.';
COMMENT ON FUNCTION erp.command_record_manual_deur_activity(jsonb) IS 'Office-only, MANUAL_WEB-only activity transcription. The first physical activity can rebase creation bootstrap events without backdating server acceptance or audit timestamps.';
